#ifndef GUARD_CONSTANTS_HITS_H
#define GUARD_CONSTANTS_HITS_H

/*
 * Hit kinds (#155 run 6, the owner's decision D6). Task.hitKind is the kind
 * of the last hit the collision engine recorded on a task (src/hitbox_*.c),
 * read by the hit reactions. Generated by tools/constants.py; each define is
 * logged with its evidence in docs/analysis/constants.csv.
 */

/* Hit kinds - Task.hitKind: the hit engine's result on a task (src/hitbox_*.c), dispatched by ActorReactToHitKind (src/actor_692fc.c) and the player's sub_08033414 (src/player_32688.c) */
#define HIT_KIND_NONE    0
#define HIT_KIND_DEFEAT  1 /* health used up */
#define HIT_KIND_DAMAGE  2
#define HIT_KIND_INHALE  3 /* inhaled by a player */
#define HIT_KIND_GRAB    4 /* grabbed and held by a player (Throw, Backdrop) */

/* Hit effects of the attaching hits - Task.hitEffect with HIT_KIND_INHALE / HIT_KIND_GRAB: the class-20 body box kind (src/hitbox_1b24c.c:233/240), which ActorAttachToHitter dispatches on (src/actor_6b2e4.c:464) */
#define HIT_EFFECT_INHALE    1 /* sites only: Task.hitEffect means other things with other hit kinds */
#define HIT_EFFECT_THROW     2
#define HIT_EFFECT_BACKDROP  3

#endif // GUARD_CONSTANTS_HITS_H
